const round=n=>Math.round(n*1000)/1000;
// Stable constructor order; rigs animate locally and never travel over the network.
export function sceneCodec(mode){const people=mode.actors,nodes=[];const visit=o=>{if(people.includes(o))return;nodes.push(o);for(const child of o.children)visit(child);};for(const o of mode.world.stage.children)visit(o);let old=new Map();return{
 capture(full=false){const changes=[];nodes.forEach((o,i)=>{const row=[i,...o.position.toArray().map(round),...o.rotation.toArray().slice(0,3).map(round),...o.scale.toArray().map(round),o.visible?1:0];const color=o.material?.color;if(color)row.push(color.getHex());const key=row.join(',');if(full||old.get(i)!==key){changes.push(row);old.set(i,key);}});return{nodes:changes,people:people.map(p=>[...p.position.toArray().map(round),p.rotation.y,p.visible?1:0,p.userData.run||0,p.userData.jump||0,p.userData.pose||'idle',p.userData.kick||0,p.userData.lean||0])};},
 apply(frame){for(const row of frame.nodes){const o=nodes[row[0]];if(!o)continue;o.position.set(...row.slice(1,4));o.rotation.set(...row.slice(4,7));o.scale.set(...row.slice(7,10));o.visible=!!row[10];if(row.length>11)o.material?.color?.setHex(row[11]);}frame.people.forEach((row,i)=>{const p=people[i];if(!p)return;p.userData.networkTarget=row;p.visible=!!row[4];Object.assign(p.userData,{run:row[5],jump:row[6],pose:row[7],kick:row[8],lean:row[9]});});},
 interpolate(dt){for(const p of people){const r=p.userData.networkTarget;if(!r)continue;const amount=1-Math.exp(-22*dt);p.position.x+=(r[0]-p.position.x)*amount;p.position.y+=(r[1]-p.position.y)*amount;p.position.z+=(r[2]-p.position.z)*amount;p.rotation.y+=Math.atan2(Math.sin(r[3]-p.rotation.y),Math.cos(r[3]-p.rotation.y))*amount;}}
};}
